responses:
{
  "summary": "Added a boolean extractor quality tracking whether the bank alarm has been tripped, so later beats can gate on the heist going loud.",
  "ops": [
    {
      "kind": "addQuality",
      "quality": {
        "key": "alarm_tripped",
        "type": "bool",
        "source": "extractor",
        "rubric": "Has the bank alarm been triggered? true only when the prose shows the alarm sounding, lights flashing, or guards reacting to a tripped alarm.",
        "read_as": "choice"
      }
    }
  ]
}

{
  "summary": "Added an int quality 'guards_knocked_out' that counts how many guards the crew has knocked out, sourced from the extractor with a monotonic flag so the count only rises as the story progresses.",
  "ops": [
    {
      "kind": "addQuality",
      "quality": {
        "key": "guards_knocked_out",
        "type": "int",
        "source": "extractor",
        "rubric": "How many guards has the crew knocked out so far in the story? Count each distinct guard the prose shows being knocked out; do not count guards merely threatened or avoided.",
        "monotonic": true
      }
    }
  ]
}

{
  "summary": "I'll propose a compact quality set for a blank format-2 story: a few extractor-read dramatic state qualities (tension, trust, commitment, danger, and a boolean for whether the protagonist has crossed a point of no return), plus a code-driven chance roll for an ambush-style beat. Since the premise is still blank, these are deliberately generic and easy to rename or prune once the story's specifics arrive.",
  "ops": [
    {
      "kind": "addQuality",
      "quality": {
        "key": "tension",
        "type": "int",
        "source": "extractor",
        "rubric": "How tense is the current scene? 0 = calm and safe, 1 = mild unease, 2 = open conflict or imminent threat, 3 = life-or-death stakes in the immediate moment.",
        "read_as": "rating"
      }
    },
    {
      "kind": "addQuality",
      "quality": {
        "key": "trust",
        "type": "int",
        "source": "extractor",
        "rubric": "How much does the protagonist trust the main companion right now? 0 = active distrust, 1 = wary, 2 = neutral, 3 = trusting, 4 = would risk their life on them.",
        "read_as": "rating",
        "monotonic": true
      }
    },
    {
      "kind": "addQuality",
      "quality": {
        "key": "commitment",
        "type": "enum",
        "source": "extractor",
        "rubric": "What has the protagonist openly committed to doing in this story? Answer 'none' if they have not stated a goal aloud, 'personal' if they have named a private goal, 'shared' if they have agreed to a goal with another character, 'oath' if they have sworn a binding promise.",
        "values": ["none", "personal", "shared", "oath"],
        "read_as": "choice",
        "latching": true
      }
    },
    {
      "kind": "addQuality",
      "quality": {
        "key": "danger",
        "type": "int",
        "source": "extractor",
        "rubric": "How much immediate physical danger is the protagonist in? 0 = safe, 1 = a known threat nearby, 2 = being actively hunted or pursued, 3 = in combat or trapped with an enemy.",
        "read_as": "rating"
      }
    },
    {
      "kind": "addQuality",
      "quality": {
        "key": "point_of_no_return",
        "type": "bool",
        "source": "extractor",
        "rubric": "Has the protagonist done something that cannot be undone — burned a bridge, killed someone, revealed a secret, or crossed a threshold they cannot walk back? true only when the prose shows the act itself, not a plan to do it.",
        "read_as": "choice",
        "latching": true
      }
    },
    {
      "kind": "addQuality",
      "quality": {
        "key": "ambush_roll",
        "type": "bool",
        "source": "code",
        "rubric": "Seeded chance roll: true when the die comes up 1 or 2 on a d6, meaning an ambush triggers on this beat.",
        "roll": { "sides": 6, "target": 2 }
      }
    }
  ]
}

{
  "summary": "Declared the core dramatic qualities for the story: tension (rated 1-5), trust (rated 1-5), a latching boolean for whether the protagonist has committed to the journey, and danger (rated 1-5). These give the extractor clear, prose-visible questions to answer each turn.",
  "ops": [
    {
      "kind": "addQuality",
      "quality": {
        "key": "tension",
        "type": "int",
        "source": "extractor",
        "read_as": "rating",
        "rubric": "from 1 (calm, nothing at stake) to 5 (peak, immediate threat or irreversible choice)",
        "criteria": {
          "levels": [
            { "value": 1, "label": "calm", "description": "Nothing is at stake; the scene is relaxed or routine." },
            { "value": 2, "label": "stirring", "description": "A hint of unease or anticipation, but no real pressure yet." },
            { "value": 3, "label": "tense", "description": "Clear stakes and friction; characters are on edge or at odds." },
            { "value": 4, "label": "critical", "description": "Imminent danger or a decision that cannot be walked back." },
            { "value": 5, "label": "peak", "description": "Immediate threat or an irreversible choice happening right now." }
          ]
        }
      }
    },
    {
      "kind": "addQuality",
      "quality": {
        "key": "trust",
        "type": "int",
        "source": "extractor",
        "read_as": "rating",
        "monotonic": true,
        "rubric": "from 1 (wary, withholding) to 5 (fully trusting, would risk themselves for the other)",
        "criteria": {
          "levels": [
            { "value": 1, "label": "wary", "description": "Openly guarded; expects betrayal or hidden motives." },
            { "value": 2, "label": "cautious", "description": "Willing to talk, but keeps secrets and watches for lies." },
            { "value": 3, "label": "cooperative", "description": "Works together on shared goals without full openness." },
            { "value": 4, "label": "reliant", "description": "Shares real fears and plans; counts on the other in danger." },
            { "value": 5, "label": "devoted", "description": "Would risk themselves for the other without hesitation." }
          ]
        }
      }
    },
    {
      "kind": "addQuality",
      "quality": {
        "key": "committed",
        "type": "bool",
        "source": "extractor",
        "read_as": "choice",
        "latching": true,
        "rubric": "Has the protagonist agreed aloud to undertake the journey or quest? true only when they say yes in dialogue or narration, not merely when they consider it."
      }
    },
    {
      "kind": "addQuality",
      "quality": {
        "key": "danger",
        "type": "int",
        "source": "extractor",
        "read_as": "rating",
        "rubric": "from 1 (safe, no threat present) to 5 (lethal, death or ruin is imminent)",
        "criteria": {
          "levels": [
            { "value": 1, "label": "safe", "description": "No threat present; the environment is secure." },
            { "value": 2, "label": "uneasy", "description": "Something feels wrong, but no threat has shown itself." },
            { "value": 3, "label": "threatened", "description": "A known danger is near or a hostile party is present." },
            { "value": 4, "label": "perilous", "description": "Violence or disaster is likely within the scene." },
            { "value": 5, "label": "lethal", "description": "Death or ruin is imminent and unavoidable without action." }
          ]
        }
      }
    }
  ]
}

{
  "summary": "Added an intermediate checkpoint 'The Lobby Door' between Casing the Bank and The Vault, where the crew cracks the lobby door. Wired transitions so the start can reach the lobby, and the lobby leads to the vault once the door is open. Introduced a 'lobby_door_open' quality to gate the lobby-to-vault transition.",
  "ops": [
    {
      "kind": "addQuality",
      "quality": {
        "key": "lobby_door_open",
        "type": "bool",
        "source": "extractor",
        "rubric": "Has the crew opened or bypassed the bank's lobby door?"
      }
    },
    {
      "kind": "addCheckpoint",
      "checkpoint": {
        "id": "lobby",
        "name": "The Lobby Door",
        "objective": "Crack the bank's lobby door and get the crew inside.",
        "type": "intermediate",
        "tension_target": "tense"
      }
    },
    {
      "kind": "addTransition",
      "transition": {
        "from": "start",
        "to": "lobby",
        "priority": 1,
        "gate": { "q": "has_key", "op": "==", "v": true }
      }
    },
    {
      "kind": "addTransition",
      "transition": {
        "from": "lobby",
        "to": "vault",
        "priority": 1,
        "gate": { "q": "lobby_door_open", "op": "==", "v": true }
      }
    }
  ]
}

