      "kind": "addCheckpoint",
      "checkpoint": {
        "id": "sun_door",
        "name": "The Sun Door",
        "objective": "Solve the sun door puzzle to open the way into the inner chamber.",
        "type": "intermediate",
        "tension_target": "tense",
        "state_snapshot": {
          "torch_lit": true
        },
        "guidance": "The sun door is a massive stone slab carved with a solar disc and rotating rings. Light must be cast through the correct alignment to trigger the mechanism. The party has a lit torch; the puzzle can be solved by positioning the torch and rotating the rings. If the torch is not lit, the door cannot be opened until a light source is found."
      }
    },
    {
      "kind": "addTransition",
      "transition": {
        "from": "ruins",
        "to": "sun_door",
        "gate": {
          "q": "torch_lit",
          "op": "==",
          "v": true
        },
        "priority": 1
      }
    },
    {
      "kind": "addTransition",
      "transition": {
        "from": "sun_door",
        "to": "chamber",
        "gate": {
          "q": "torch_lit",
          "op": "==",
          "v": true
        },
        "priority": 1
      }
    }
  ]
}

