{
  "summary": "Added Vex to the roster as the crew's lockpick — nervous but brilliant. No checkpoint effects or cast_changes yet, since the draft has no card names or entry beats defined; Vex is present from the start by default.",
  "ops": [
    {
      "kind": "addRosterMember",
      "member": {
        "id": "vex",
        "name": "Vex",
        "role": "The crew's lockpick — cracks safes and tumbles cylinders under pressure.",
        "drive": "Prove she's the best in the city before her nerve gives out."
      }
    }
  ]
}

{
  "summary": "The story's own lorebook 'Vault Job Lore' already exists, so no lorebook creation is needed. The only cast member named by the draft is Vex, who is not on this install, so I'll create her card with a first message for the opening 'Casing the Bank' scene. I'll also create the group that plays the story, listing Vex as its member. No lorebook entries are specified by the draft, so none are added.",
  "ops": [
    {
      "kind": "createCharacterCard",
      "name": "Vex",
      "description": "Vex is the crew's lockpick: a wiry, sharp-eyed thief with quick hands and a quicker tongue. She reads locks the way other people read faces, and she's never met a door she couldn't talk her way through — given enough time and the right tools.",
      "role": "The crew's lockpick",
      "personality": "Wry, impatient, precise. Talks while she works. Distrusts anyone who won't get their hands dirty.",
      "scenario": "Vex is casing the city bank with the crew, scouting the vault door and the guards' routines before the job.",
      "first_mes": "*Vex crouches by the bank's side entrance, a slim pick already turning between her fingers. She glances up as you approach.*\n\n\"There you are. I've been staring at this door for ten minutes and I'm bored out of my mind. It's a good lock — too good for a bank this size, which means somebody upstairs is paranoid.\" *She nods toward the main hall.* \"Guards change shift at the top of the hour. We've got a window. What's the plan — do we go in quiet, or do you want to make some noise?\"",
      "tags": ["thief", "lockpick", "heist"]
    },
    {
      "kind": "createGroup",
      "name": "The Vault Job Crew",
      "members": ["Vex"]
    }
  ]
}

{
  "summary": "Added an intermediate checkpoint 'The Ossuary' between the entrance and the crypt, where the party discovers the relic is a fake. It sits on the existing door_open transition path, so the entrance still gates on the door, and the ossuary now bridges to the crypt.",
  "ops": [
    {
      "kind": "addCheckpoint",
      "checkpoint": {
        "id": "ossuary",
        "name": "The Ossuary",
        "objective": "The party finds the relic in the ossuary and realizes it is a fake.",
        "type": "intermediate",
        "tension_target": "stirring",
        "guidance": "The ossuary is a side chamber of stacked bones. The relic the party sought is here, but it is a forgery — a gilded copy. Let the discovery land before the party pushes on toward the crypt."
      }
    },
    {
      "kind": "addTransition",
      "transition": {
        "from": "entrance",
        "to": "ossuary",
        "priority": 1,
        "gate": { "q": "door_open", "op": "==", "v": true }
      }
    },
    {
      "kind": "addTransition",
      "transition": {
        "from": "ossuary",
        "to": "crypt",
        "priority": 1
      }
    }
  ]
}

