{
  "summary": "Added a final anchor checkpoint, The Wreck, where the crew abandons the ship carrying the captain's log. No transitions added at this stage.",
  "ops": [
    {
      "kind": "addCheckpoint",
      "checkpoint": {
        "id": "wreck",
        "name": "The Wreck",
        "objective": "Abandon the drifting ship, carrying the captain's log.",
        "type": "anchor",
        "tension_target": "peak",
        "state_snapshot": {
          "boarded": true,
          "log_read": true
