{
  "summary": "Added a latching boolean quality `door_open` (already present) and set a state snapshot on The Crypt so that arriving there forces `door_open` to true. This guarantees the door counts as open once the party reaches the crypt, regardless of how they got in.",
  "ops": [
    {
      "kind": "updateQuality",
      "key": "door_open",
      "patch": {
        "latching": true
      }
    },
    {
      "kind": "setCheckpointSnapshot",
      "id": "crypt",
      "snapshot": {
        "door_open": true
      }
    }
  ]
}

{
  "summary": "Wired the two requested transitions: fog→deck gated on the crew having boarded, and deck→cabin gated on the captain's log having been read. Both carry a progress effect toward their target anchor so the convergence threshold is reachable.",
  "ops": [
    {
      "kind": "addTransition",
      "transition": {
        "from": "fog",
        "to": "deck",
        "gate": { "q": "boarded", "op": "==", "v": true },
        "priority": 1,
        "effects": { "progress": { "anchor": "deck", "amount": 1 } },
        "extraction_hint": "the crew steps off the boat and onto the drifting ship's deck"
      }
    },
    {
      "kind": "addTransition",
      "transition": {
        "from": "deck",
        "to": "cabin",
        "gate": { "q": "log_read", "op": "==", "v": true },
        "priority": 1,
        "effects": { "progress": { "anchor": "cabin", "amount": 1 } },
        "extraction_hint": "the captain's log is opened and its final entries are read"
      }
    }
  ]
}

{
  "summary": "Added an author's note to The Fog checkpoint: the fog swallows every sound.",
  "ops": [
    {
      "kind": "setCheckpointEffects",
      "id": "fog",
